userscript.function:

	doSelectCopyClientCallback();

    if (mode == 'new') {
        formObj.showItem('CLIENT_CODE_CHECK');
        formObj.showItem('CLIENT_COPY');
        formObj.setReadonly('CLIENT_CODE', false);
        formObj.setReadonly('SERVICE_URL', false);
        formObj.setValue('COMPANY_CODE', '1000');

        var tabbarObj = getOAObject('AD_402').tabbarObj;
        callFunction('AD_402', 'tabActivate', [tabbarObj.tabs('MODULE'), false]);
        callFunction('AD_402', 'tabActivate', [tabbarObj.tabs('DESIGN'), false]);
        callFunction('AD_402', 'tabActivate', [tabbarObj.tabs('NOTIFICATION'), false]);
        callFunction('AD_401', 'listUnselectAll', []);

        createFlag = false;
    } else if (mode == 'default') {
        formObj.hideItem('CLIENT_CODE_CHECK');
        formObj.hideItem('CLIENT_COPY');
        formObj.setReadonly('CLIENT_CODE', true);
        formObj.setReadonly('SERVICE_URL', true);

        createFlag = true;
    }


if (!formObj.validateItem('CLIENT_CODE')) {
    Alert(Sepoa.cache.text.get('MESSAGE.0002'));
    return;
}

doServiceAjax('sepoa.svc.admin.AD_400', 'CONNECTION', 'doCheckDuplicate', null, function(so) {
    if (so.status != 1) {
        Alert(Sepoa.cache.text.get('MESSAGE.1002'));
        return;
    }

    var sf = new SepoaFormater(so.result[0]);

    if (sf.getArrayMap().length == 0) {
        createFlag = true;
        Alert(Sepoa.cache.text.get('AD_405.DO_NOT_DUPLICATE'));
    } else {
        createFlag = false;
        Alert(Sepoa.cache.text.get('AD_405.DUPLICATE'));
    }
});


formObj.setItemLabel('CLIENT_COPY', sUtils.cache.text.get('AD_405.CLIENT_COPY'));
dataOutput.setValue('COPY_CLIENT_CODE', '');

if(code) {
	var msg = sUtils.string.dataReplacer(sUtils.cache.text.get('AD_405.COPY_TO_CLIENT_CODE'), {CODE: code});
	formObj.setItemLabel('CLIENT_COPY', msg);
	dataOutput.setValue('COPY_CLIENT_CODE', code);
}


changeMode('default');

var params = {
    CLIENT_CODE: clientCode,
    COMPANY_CODE: companyCode
};

if (createNewObj) {
    params = $.extend(true, params, createNewObj);
}

doServiceAjax('sepoa.svc.admin.AD_405', 'CONNECTION', 'doQueryForm', params, function(so) {
    if (so.status != 1) {
        Alert(Sepoa.cache.text.get('MESSAGE.1002'));
        return;
    }

    var sf = new SepoaFormater(so.result[0]);

    formObj.dataMapper(sf);
});


if (!formObj.validate()) {
    Alert(Sepoa.cache.text.get('MESSAGE.0002'))
    return;
}

if (createFlag == false) {
    Alert(Sepoa.cache.text.get('AD_405.DUPLICATE_CHECK_AGAIN'));
    return;
}

Confirm(Sepoa.cache.text.get('AD_405.SAVE_AND_SERVER_RELOAD'), function(flag) {
    if (flag) {
        var params = $.extend(true, formObj.getFormData(), {
            SERVICE_FROM: formObj.getValue('SERVICE_FROM'),
            SERVICE_TO: formObj.getValue('SERVICE_TO'),
            COPY_CLIENT_CODE: dataOutput.getValue('COPY_CLIENT_CODE')
        });

        doServiceAjax('sepoa.svc.admin.AD_405', 'TRANSACTION', 'doSaveForm', params, function(so) {
            if (so.status != 1) {
                Alert(Sepoa.cache.text.get('MESSAGE.1002'));
                return;
            }

            Alert(Sepoa.cache.text.get('MESSAGE.0001'));

            callFunction('AD_401', 'doQuery', []);
        })
    }
});
